import base64, hashlib, json, pathlib, subprocess, lzma
PATCH = ''
CHECKSUM = '63c9d9545e8692768b9d0fcc774913d9d3ac54e3a2f9c9519304e3a7fd54439c'
def run(*args):
    return subprocess.check_output(args, text=True).strip()
assert run('git','rev-parse','HEAD') == '1ea8addb6689ece2b11342df3381fc3a9f39adc2'
patch = lzma.decompress(base64.b64decode(PATCH))
assert hashlib.sha256(patch).hexdigest() == CHECKSUM
pathlib.Path('/tmp/storage.patch').write_bytes(patch)
subprocess.run(['git','apply','--check','--unidiff-zero','/tmp/storage.patch'], check=True)
subprocess.run(['git','apply','--unidiff-zero','/tmp/storage.patch'], check=True)
subprocess.run(['git','diff','--check'],check=True)
run('git','config','user.name','github-actions[bot]')
run('git','config','user.email','41898282+github-actions[bot]@users.noreply.github.com')
run('git','add','Package.swift','Sources/LakeOfFireContent/Files/ReaderFileManager.swift','Sources/LakeOfFireReader/Reader/Books/EbookFileManager.swift','Tests/LakeOfFireTests/ReviewReaderStorageSafetyTests.swift')
run('git','commit','-m','fix: preserve backing identity and incomplete inventories; retry EPUB enrichment')
head=run('git','rev-parse','HEAD')
run('git','push','origin','HEAD:refs/heads/review/20260917-storage-identity-enrichment')
pathlib.Path('/tmp/review-output/publication.json').write_text(json.dumps({'head':head,'tree':run('git','rev-parse','HEAD^{tree}'),'base':'1ea8addb6689ece2b11342df3381fc3a9f39adc2','patchSHA256':CHECKSUM,'nativeTests':'NOT RUN'},indent=2))
